from __future__ import annotations

import unittest

from common import RepoFixture

from publishing_house.generate import generate_content
from publishing_house.verify import verify_content
from publishing_house.generators import registry


class ContentGenerationAndVerificationTests(unittest.TestCase):
    """The core promise: content is generated by code and verified by code."""

    def setUp(self) -> None:
        self.fixture = RepoFixture()

    def tearDown(self) -> None:
        self.fixture.close()

    def test_registry_covers_the_four_product_families(self) -> None:
        # Puzzle/activity, logic, journal/workbook, coloring line-art, printable.
        available = set(registry.keys())
        for content_type in ("sudoku", "wordsearch", "maze", "journal", "line-art-brief", "printable"):
            self.assertIn(content_type, available, content_type)

    def test_generation_is_deterministic_from_seed(self) -> None:
        pid, _ = self.fixture.project()
        first = generate_content(self.fixture.root, pid, "sudoku", count=5, difficulty="easy", seed=42, actor="test")
        second = generate_content(self.fixture.root, pid, "sudoku", count=5, difficulty="easy", seed=42, actor="test")
        # Same seed produces the same content hash.
        self.assertEqual(first["sha256"], second["sha256"])
        self.assertTrue(first["sha256"].startswith("sha256:"))
        self.assertEqual(5, first["count"])

    def test_independent_verification_passes_generated_content(self) -> None:
        pid, _ = self.fixture.project()
        generate_content(self.fixture.root, pid, "sudoku", count=6, difficulty="mixed", seed=99, actor="test")
        result = verify_content(self.fixture.root, pid, "sudoku")
        self.assertEqual("PASS", result["decision"], result)
        self.assertEqual(0, result["failed_batch_count"], result)
        self.assertGreaterEqual(result["item_count"], 6)

    def test_verification_reports_when_nothing_generated(self) -> None:
        pid, _ = self.fixture.project()
        result = verify_content(self.fixture.root, pid, "wordsearch")
        # Not-run is never a silent pass.
        self.assertNotEqual("PASS", result.get("decision"))


if __name__ == "__main__":
    unittest.main()
